 static Tag[][] ReadTags(){using var b=new BinaryReader(new MemoryStream(TagBytes));int nv=b.ReadInt32(),ns=b.ReadInt32();var result=new Tag[ns][];for(int sm=0;sm<ns;sm++){int role=b.ReadInt32(),n=b.ReadInt32();for(int i=0;i<n*3;i++)b.ReadInt32();result[sm]=new Tag[n];for(int i=0;i<n;i++)result[sm][i]=new Tag{part=b.ReadInt32(),flag=b.ReadInt32(),global=b.ReadInt32()};}return result;}
 static void Project(Matrix4x4 v,Matrix4x4 p,Vector3 a,out double x,out double y){double[] q=new double[4];for(int i=0;i<4;i++)q[i]=(double)v[i,0]*a.x+(double)v[i,1]*a.y+(double)v[i,2]*a.z+v[i,3];double xx=0,yy=0,w=0;for(int i=0;i<4;i++){xx+=p[0,i]*q[i];yy+=p[1,i]*q[i];w+=p[3,i]*q[i];}x=(xx/w*.5+.5)*GW;y=(.5-yy/w*.5)*GH;}
 static List<Piece> Envelope(Input input,Tag[][]tags,Vector3[]world,Vector2[]uv,int[]ix,out double[]px,out double[]py){px=new double[world.Length];py=new double[world.Length];for(int i=0;i<world.Length;i++)Project(input.camera.worldToCameraMatrix,input.camera.projectionMatrix,world[i],out px[i],out py[i]);var edges=new List<Edge>();var seen=new HashSet<ulong>();for(int pr=0;pr<ix.Length/3;pr++)if(tags[3][pr].part==Part)for(int k=0;k<3;k++){int a=ix[pr*3+k],b=ix[pr*3+(k+1)%3];ulong key=((ulong)(uint)Math.Min(a,b)<<32)|(uint)Math.Max(a,b);if(!seen.Add(key)||Math.Abs(py[b]-py[a])<1e-10)continue;double lo=Math.Max(Y0,Math.Min(py[a],py[b])),hi=Math.Min(Y1+1,Math.Max(py[a],py[b]));if(hi<=lo)continue;double slope=(px[b]-px[a])/(py[b]-py[a]);edges.Add(new Edge{a=a,b=b,primitive=pr,global=tags[3][pr].global,lo=lo,hi=hi,slope=slope,offset=px[a]-slope*py[a]});}
