 return pieces;}
 static double SegmentDistance(CurvePoint p,CurvePoint a,CurvePoint b){double dx=b.x-a.x,dy=b.y-a.y,t=Math.Max(0,Math.Min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy+1e-30)));return Math.Sqrt(Math.Pow(p.x-a.x-t*dx,2)+Math.Pow(p.y-a.y-t*dy,2));}
 static List<CurvePoint> Simplify(List<CurvePoint>a){if(a.Count<3)return a;double best=0;int at=0;for(int i=1;i<a.Count-1;i++){double d=SegmentDistance(a[i],a[0],a.Last());if(d>best){best=d;at=i;}}if(best<=SimplifyError)return new List<CurvePoint>{a[0],a.Last()};var left=Simplify(a.Take(at+1).ToList());left.RemoveAt(left.Count-1);left.AddRange(Simplify(a.Skip(at).ToList()));return left;}
 static double CurveX(List<Piece>p,double y){var s=p.FirstOrDefault(v=>v.y0<=y+1e-8&&v.y1>=y-1e-8);if(s==null)return double.NaN;return s.x0+s.slope*(y-s.y0);}
 static double ReferenceX(List<CurvePoint>p,double y){for(int i=1;i<p.Count;i++)if(y<=p[i].y+1e-9)return p[i-1].x+(p[i].x-p[i-1].x)*(y-p[i-1].y)/(p[i].y-p[i-1].y);return p.Last().x;}
 static string FenceReason(Input a,int x,int y){if(x<4||x>=GW-4||y<4||y>=GH-4)return "격자 경계";for(int dy=-Fence;dy<=Fence;dy++)for(int dx=-Fence;dx<=Fence;dx++){int q=LI(x+dx,y+dy);var m=a.centreSurface[q];if(m.r>0&&!Arm(m,a.centrePalette[q]))return "다른 owner/material/blend의 3셀 특징 잠금";if(Round(a.line[LI(x+dx,y+dy)].r)==2)return "안쪽 owned line의 3셀 특징 잠금";}return null;}
 static Vector3 Closest(Vector3 p,Vector3 a,Vector3 b,Vector3 c){Vector3 ab=b-a,ac=c-a,ap=p-a;float d1=Vector3.Dot(ab,ap),d2=Vector3.Dot(ac,ap);if(d1<=0&&d2<=0)return a;Vector3 bp=p-b;float d3=Vector3.Dot(ab,bp),d4=Vector3.Dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+ab*(d1/(d1-d3));Vector3 cp=p-c;float d5=Vector3.Dot(ab,cp),d6=Vector3.Dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+ac*(d2/(d2-d6));float va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0)return b+(c-b)*((d4-d3)/((d4-d3)+(d5-d6)));float den=1/(va+vb+vc);return a+ab*(vb*den)+ac*(vc*den);}
 static bool Finite(float v)=>!float.IsNaN(v)&&!float.IsInfinity(v);
 static Sample NewPoint(Input a,int x,int y,Vector3[]world,Vector2[]uv,int[]ix,Tag[][]tags,List<Tri>external,Receipt receipt){var candidates=new List<Sample>();for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++){if(dx==1&&dy==0)continue;int nx=2*x+dx,ny=2*y+dy,ni=NI(nx,ny);var m=a.surface[ni];if(!Arm(m,a.palette[ni]))continue;int pr=Round(m.a)-11118;if(pr<0||pr>=ix.Length/3||tags[3][pr].global!=Round(m.a)||tags[3][pr].part!=Part||tags[3][pr].flag!=0)continue;var c=a.corr[0][ni];var w=a.corr[1][ni];var lit=a.corr[2][ni];var shade=a.corr[3][ni];if(Round(c.b)!=11||Round(c.a)!=pr+1||w.a<.5||!Finite(c.r)||!Finite(c.g)||lit.a<.999||shade.a<.999){receipt.inputRejections.Add($"P{a.phase:00} ({x},{y}) native({nx},{ny}): GPU UV/owner/alpha 대응 부족");continue;}
 Vector3 p=new Vector3(w.r,w.g,w.b),v0=world[ix[pr*3]],v1=world[ix[pr*3+1]],v2=world[ix[pr*3+2]],ab=v1-v0,ac=v2-v0,ap=p-v0;double d00=Vector3.Dot(ab,ab),d01=Vector3.Dot(ab,ac),d11=Vector3.Dot(ac,ac),d20=Vector3.Dot(ap,ab),d21=Vector3.Dot(ap,ac),den=d00*d11-d01*d01;if(Math.Abs(den)<1e-20)continue;float b1=(float)((d11*d20-d01*d21)/den),b2=(float)((d00*d21-d01*d20)/den);Vector3 bary=new Vector3(1-b1-b2,b1,b2);Vector3 reconstructed=v0*bary.x+v1*bary.y+v2*bary.z;Vector2 sourceUV=uv[ix[pr*3]]*bary.x+uv[ix[pr*3+1]]*bary.y+uv[ix[pr*3+2]]*bary.z;double we=Vector3.Distance(p,reconstructed),ue=Vector2.Distance(sourceUV,new Vector2(c.r,c.g));if(bary.x<-.002||bary.y<-.002||bary.z<-.002||we>.00005||ue>.0005){receipt.inputRejections.Add($"P{a.phase:00} ({x},{y}) native({nx},{ny}): source 삼각형 UV/world 오차 {ue:R}/{we:R}");continue;}
 double gap=double.PositiveInfinity;foreach(var t in external){double d=(Closest(p,t.a,t.b,t.c)-p).sqrMagnitude;if(d<gap)gap=d;}gap=Math.Sqrt(gap);if(gap<=a.worldCell){receipt.inputRejections.Add($"P{a.phase:00} ({x},{y}) native({nx},{ny}): 1셀 이하 외부 표면 {gap:R}; 정확한 caster/alpha 분류 추가 입력 필요");continue;}
 var form=new Color(0,1,0,1); // Common330/331 already supplies current actual source colour. UV/world/source-triangle and current external-distance proofs above replace the obsolete frozen312 screen cache gate.

 var packet=new PointPacket{cell=new[]{x,y},native=new[]{nx,ny},primitive=pr,global=Round(m.a),part=Part,role=10,world=p,barycentric=bary,uv=new Vector2(c.r,c.g),sourceUV=sourceUV,own=a.signals[3][ni],lit=lit,shade=shade,chosen=lit,physical=a.signals[2][ni],form=form,worldError=we,uvError=ue,closestExternalDistance=gap,classification=1,rule="같은 UV의 GPU 원색/끝점 + 같은 bone form. 모든 다른 부위 실제 triangle까지 1논리셀 이상 거리로 near-overlap 없음 입증. 원래312 knownNoNear 규칙; 임의 물리 fallback/다른 피부/회색 평균 없음."};candidates.Add(new Sample{x=nx,y=ny,packet=packet});}
 // 색 표본 순서는 경계 선택 비용에 영향을 주지 않는다. 같은 셀 안에서 중심에 가장 가까운 표본, 동률은 native y/x 순.
 return candidates.OrderBy(s=>Math.Pow(s.x+.5-(2*x+1),2)+Math.Pow(s.y+.5-(2*y+1),2)).ThenBy(s=>s.y).ThenBy(s=>s.x).FirstOrDefault();}
 static List<Tri> External(Input a,Tag[][]tags){var list=new List<Tri>();for(int r=0;r<a.renderers.Length;r++){var rr=a.renderers[r];var mesh=rr.GetComponent<MeshFilter>().sharedMesh;var w=mesh.vertices.Select(v=>rr.transform.TransformPoint(v)).ToArray();for(int sm=0;sm<mesh.subMeshCount;sm++){var ix=mesh.GetIndices(sm);for(int pr=0;pr<ix.Length/3;pr++){int part=r==0?tags[sm][pr].part:0;if(r==0&&part==Part)continue;list.Add(new Tri{a=w[ix[pr*3]],b=w[ix[pr*3+1]],c=w[ix[pr*3+2]],part=part});}}}return list;}
 static double SpanPenalty(Node n,int delta,out int sign,out int run,out int last,out int previous){sign=n.lastSign;run=n.run;last=n.lastRun;previous=n.previousRun;double cost=0;if(delta==0){run++;return 0;}int ds=Math.Sign(delta);if(sign!=0&&ds!=sign)cost+=1.0/Math.Max(1,run);if(last>0&&previous>0&&(last-previous)*(run-last)<0)cost+=.5;previous=last;last=run;run=1;sign=ds;return cost;}
 public static Output Build(Input a){Y0=a.y0;Y1=a.y1;var receipt=new Receipt{phase=a.phase,status="입력 검사 중"};receipt.logicalInterval=new[]{Y0,Y1};var tags=ReadTags();var body=a.renderers[0];var mesh=body.GetComponent<MeshFilter>().sharedMesh;var world=mesh.vertices.Select(v=>body.transform.TransformPoint(v)).ToArray();var uv=mesh.uv;var ix=mesh.GetIndices(3);var pieces=Envelope(a,tags,world,uv,ix,out var px,out var py);receipt.sourcePieces=pieces;if(pieces.Count==0)throw new Exception("319 연속 소스 윤곽 없음");var vertices=new List<CurvePoint>{new CurvePoint{x=pieces[0].x0,y=pieces[0].y0,edgeA=pieces[0].a,edgeB=pieces[0].b,primitive=pieces[0].primitive,global=pieces[0].global}};vertices.AddRange(pieces.Select(s=>new CurvePoint{x=s.x1,y=s.y1,edgeA=s.a,edgeB=s.b,primitive=s.primitive,global=s.global}));var reference=Simplify(vertices);receipt.reference=reference;var external=External(a,tags);int count=Y1-Y0+1;var options=new List<Option>[count];var old=new int[count];var sourceX=new double[count];var refX=new double[count];var map=new Color[GW*GH];
 for(int i=0;i<count;i++){int y=Y0+i;double sx=CurveX(pieces,y+.5),rx=ReferenceX(reference,y+.5);sourceX[i]=sx;refX[i]=rx;int q=-1;for(int x=0;x<GW;x++)if(Frontier(a.centreSurface[LI(x,y)],a.centrePalette[LI(x,y)]))q=x;old[i]=q;var row=new Row{y=y,original=q,chosen=q,sourceX=sx,referenceX=rx,endpoint=i==0||i==count-1};var rejects=new List<string>();options[i]=new List<Option>{new Option{q=q}};
 if(!row.endpoint&&q>=0&&!double.IsNaN(sx)&&Math.Abs(q+1-sx)<=MaxBoundaryError){foreach(int target in new[]{q-1,q+1}){if(Math.Abs(target+1-sx)>MaxBoundaryError+1e-9)continue;int changedX=target<q?q:target;string reason=FenceReason(a,changedX,y);if(reason!=null){rejects.Add(target+":"+reason);continue;}if(target<q){if(!a.backgroundUniform&&!a.underlayAvailable){rejects.Add(target+":실제 배경 상수 증명 없음; underlay 입력 필요");continue;}if(!Arm(a.centreSurface[LI(q-1,y)],a.centrePalette[LI(q-1,y)])){rejects.Add(target+":안쪽 연속성 부족");continue;}options[i].Add(new Option{q=target});}else{if(a.centreSurface[LI(target,y)].r>0){rejects.Add(target+":배경이 아닌 owner");continue;}var sample=NewPoint(a,target,y,world,uv,ix,tags,external,receipt);if(sample==null){rejects.Add(target+":같은 표면 UV/명암 계약 미충족");continue;}options[i].Add(new Option{q=target,added=sample});}}}
 row.rejections=rejects.ToArray();row.allowed=options[i].Select(o=>o.q).ToArray();receipt.rows.Add(row);}
 // 잠긴 행을 연결 끝점으로 삼아 각 연속 구간을 독립적으로 선택한다. 원래 불가시/가림 구간을 건너지 않는다.
 var selected=(int[])old.Clone();int start=0;while(start<count-1){int end=start+1;while(end<count-1&&options[end].Count>1)end++;if(end-start<2){start=end;continue;}var nodes=new List<Node>{new Node{cost=0,path=new[]{old[start]},run=1}};for(int i=start+1;i<=end;i++){var next=new List<Node>();foreach(var n in nodes)foreach(var o in options[i]){if(i==end&&o.q!=old[end])continue;int prev=n.path.Last(),d=o.q-prev;double dr=refX[i]-refX[i-1];if(Math.Abs(d)>Math.Max(1,Math.Ceiling(Math.Abs(dr))))continue;if(d!=0&&Math.Abs(dr)>1e-8&&Math.Sign(d)!=Math.Sign(dr))continue;double loc=Math.Pow(o.q+1-sourceX[i],2),orientation=.5*Math.Pow(d-dr,2);int sign,run,last,previous;double span=SpanPenalty(n,d,out sign,out run,out last,out previous);next.Add(new Node{cost=n.cost+loc+orientation+span,path=n.path.Concat(new[]{o.q}).ToArray(),lastSign=sign,run=run,lastRun=last,previousRun=previous});}nodes=next.OrderBy(n=>n.cost).ThenBy(n=>string.Join(",",n.path)).Take(BeamWidth).ToList();if(nodes.Count==0)break;}
 if(nodes.Count==0){receipt.blockedSegments++;receipt.inputRejections.Add($"P{a.phase:00} rows {Y0+start}..{Y0+end}: 끝점/회전/표면 제약을 함께 만족하는 경로 없음; 원래 구간 보존");}else{var best=nodes[0];receipt.objective+=best.cost;for(int i=start;i<=end;i++)selected[i]=best.path[i-start];}start=end;}
 for(int i=0;i<count;i++){int y=Y0+i,q=old[i],target=selected[i];receipt.rows[i].chosen=target;receipt.rows[i].direction=i==0?0:Math.Sign(refX[i]-refX[i-1]);if(q==target)continue;if(target<q){map[LI(q,y)]=new Color(-1,0,0,1);receipt.removed++;}else{var sample=options[i].Single(o=>o.q==target).added;if(sample==null)throw new Exception("319 색 입력이 없는 새 대표점");map[LI(target,y)]=new Color(1,sample.x,NH-1-sample.y,1);receipt.newPoints.Add(sample.packet);receipt.added++;}receipt.maxSourceBoundaryError=Math.Max(receipt.maxSourceBoundaryError,Math.Abs(target+1-sourceX[i]));}
 receipt.changed=receipt.added+receipt.removed;receipt.baselineFrontier=old;receipt.selectedFrontier=selected;receipt.sourceX=sourceX;receipt.status=receipt.blockedSegments>0?"일부 구간 입력/제약 차단, 나머지 동일 후보 선택 완료":"연속 소스 입력과 단일 디지털 경로 선택 완료";return new Output{map=map,receipt=receipt};}
